// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(amount > 0);
        vm.assume(sender != address(0));

        vm.deal(sender, amount);

        uint256 beforeCount = c.depositsCount();

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "call to receive failed");

        uint256 afterCount = c.depositsCount();

        assertTrue(afterCount >= beforeCount);
    }
}
